import * as T from 'three';

// Bake entire trees, preserving their silhouettes. This replaces distant trees
// with two triangles per tree, without inflating individual leaf triangles.
export function createTreeImpostor(renderer,scene,source,origin,capacity){
 const bake=new T.Scene(),root=new T.Group();bake.add(root);source.updateMatrixWorld(true);
 source.traverse(o=>{if(!o.isMesh)return;const material=new T.MeshBasicMaterial({map:o.material.map,color:o.material.color,alphaTest:.27,side:T.DoubleSide});const mesh=new T.Mesh(o.geometry.clone().applyMatrix4(origin.clone().multiply(o.matrixWorld)),material);root.add(mesh);});
 const bounds=new T.Box3().setFromObject(root),center=bounds.getCenter(new T.Vector3()),radius=bounds.getBoundingSphere(new T.Sphere()).radius*1.035,size=radius*2;
 // Array layers have independent mip chains, so tiny distant trees never
 // sample pixels from the neighboring viewing angle.
 const atlas=new T.WebGLArrayRenderTarget(256,256,24,{format:T.RGBAFormat,type:T.UnsignedByteType,minFilter:T.LinearMipmapLinearFilter,magFilter:T.LinearFilter,generateMipmaps:true});atlas.texture.name='whole-tree-24-view-array';
 const ortho=new T.OrthographicCamera(-radius,radius,radius,-radius,.1,100),previous=renderer.getRenderTarget(),clear=renderer.getClearColor(new T.Color()),alpha=renderer.getClearAlpha(),viewport=renderer.getViewport(new T.Vector4()),scissor=renderer.getScissor(new T.Vector4()),scissorTest=renderer.getScissorTest(),tone=renderer.toneMapping;
 renderer.setScissorTest(false);renderer.setClearColor(0,0);renderer.toneMapping=T.NoToneMapping;
 for(let i=0;i<24;i++){renderer.setRenderTarget(atlas,i);renderer.setViewport(0,0,256,256);renderer.clear();const angle=(i%8)*Math.PI/4,elevation=[.04,.65,1.25][Math.floor(i/8)];ortho.position.set(Math.sin(angle)*Math.cos(elevation)*20,Math.sin(elevation)*20,Math.cos(angle)*Math.cos(elevation)*20).add(center);ortho.lookAt(center);renderer.render(bake,ortho);}
 renderer.setRenderTarget(previous);renderer.setClearColor(clear,alpha);renderer.setViewport(viewport);renderer.setScissor(scissor);renderer.setScissorTest(scissorTest);renderer.toneMapping=tone;root.traverse(o=>{if(o.isMesh){o.geometry.dispose();o.material.dispose();}});
 const geo=new T.PlaneGeometry(size,size),views=new T.InstancedBufferAttribute(new Float32Array(capacity),1),previousViews=new Uint8Array(capacity).fill(255);geo.setAttribute('treeView',views);const white=new T.DataTexture(new Uint8Array([255,255,255,255]),1,1);white.needsUpdate=true;const material=new T.MeshStandardMaterial({map:white,side:T.DoubleSide,alphaTest:.24,alphaToCoverage:true,roughness:1,metalness:0,envMapIntensity:.2});material.onBeforeCompile=s=>{s.uniforms.treeAtlas={value:atlas.texture};s.vertexShader='attribute float treeView;\nvarying float vTreeView;\n'+s.vertexShader;s.vertexShader=s.vertexShader.replace('#include <uv_vertex>','#include <uv_vertex>\nvTreeView=treeView;');s.fragmentShader='uniform highp sampler2DArray treeAtlas;\nvarying float vTreeView;\n'+s.fragmentShader;s.fragmentShader=s.fragmentShader.replace('#include <map_fragment>','diffuseColor *= texture(treeAtlas,vec3(vMapUv,vTreeView));');};material.customProgramCacheKey=()=> 'whole-tree-array-v7';
 const mesh=new T.InstancedMesh(geo,material,capacity);mesh.frustumCulled=false;mesh.receiveShadow=false;mesh.count=0;scene.add(mesh);const dummy=new T.Object3D(),color=new T.Color();
 return{update(indices,positions,camera,height){let n=0;for(const index of indices){const p=positions[index],scale=p[2]/height;dummy.position.set(p[0],.06+center.y*scale,p[1]);dummy.lookAt(camera.position);dummy.scale.setScalar(scale);dummy.updateMatrix();mesh.setMatrixAt(n,dummy.matrix);const theta=Math.atan2(camera.position.x-p[0],camera.position.z-p[1])-p[3],nearest=((Math.round(theta/(Math.PI/4))%8)+8)%8,elevation=Math.atan2(camera.position.y-p[2]*.5,Math.hypot(camera.position.x-p[0],camera.position.z-p[1])),old=previousViews[index];let direction=old===255?nearest:old%8,level=old===255?(elevation>.95?2:elevation>.345?1:0):Math.floor(old/8);const delta=T.MathUtils.euclideanModulo(theta-direction*Math.PI/4+Math.PI,Math.PI*2)-Math.PI;if(Math.abs(delta)>Math.PI/8+.08)direction=nearest;if(elevation>1.03)level=2;else if(elevation<.265)level=0;else if((level===0&&elevation>.425)||(level===2&&elevation<.87))level=1;previousViews[index]=direction+level*8;views.setX(n,previousViews[index]);mesh.setColorAt(n,color.setHSL(.26+(index%11)*.002,.09,.82+(index%5)*.025));n++;}mesh.count=n;mesh.instanceMatrix.needsUpdate=true;views.needsUpdate=true;if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;},texture:atlas.texture};
}
